            # Run pytest
            try:
                result = subprocess.run(
                    [self.python_executable, '-m', 'pytest', '-v'] + test_files,
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                if result.returncode == 0:
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='pytest',
                        detail='All tests passed',
                        duration_s=time.time() - start
                    )
                else:
                    # Check for ModuleNotFoundError
                    if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                        return GateResult(
                            name='tests',
                            status=SKIPPED,
                            method='pytest',
                            detail=f"Tests skipped due to missing dependencies: {result.stderr}",
                            duration_s=time.time() - start
                        )
