            # bare def test_*() functions AND unittest.TestCase subclasses

            # We'll write a small runner script
            runner_script = """
import sys
import os
import unittest
import importlib.util

def run_tests(test_files):
    collected = 0
    failed = 0

    for test_file in test_files:
        try:
            # Add to path
            sys.path.insert(0, os.path.dirname(test_file))
            spec = importlib.util.spec_from_file_location("test_module", test_file)
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)

            # Collect bare test functions
            for name in dir(module):
                if name.startswith('test_'):
                    func = getattr(module, name)
                    if callable(func) and func.__code__.co_argcount == 0:
                        collected += 1
                        try:
                            func()
                        except Exception as e:
                            failed += 1
                            print(f"FAIL: {name}: {e}")

            # Collect unittest.TestCase subclasses
            for name in dir(module):
                cls = getattr(module, name)
                if isinstance(cls, type) and issubclass(cls, unittest.TestCase) and cls is not unittest.TestCase:
                    suite = unittest.TestLoader().loadTestsFromTestCase(cls)
                    collected += suite.countTestCases()
                    result = unittest.TextTestRunner(verbosity=0).run(suite)
                    if not result.wasSuccessful():
                        failed += len(result.failures) + len(result.errors)

        except ModuleNotFoundError as e:
            print(f"SKIP: {test_file}: {e}")
            return 'SKIPPED'
        except Exception as e:
            print(f"ERROR: {test_file}: {e}")
            return 'FAILED'

    if collected == 0:
        return 'FAILED'
    if failed > 0:
        return 'FAILED'
    return 'PASSED'

if __name__ == '__main__':
    test_files = sys.argv[1:]
    status = run_tests(test_files)
    print(status)
    sys.exit(0 if status == 'PASSED' else 1)
"""

            try:
