            path = path[:-1]
        return path

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {k: v for k, v in bundle.items() if not is_generated_path(k) and not is_malformed_path(k)}

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_generated_path(k):
                generated[k] = v
            elif is_malformed_path(k):
                malformed[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
        count = 0
        for path in bundle:
            if not is_generated_path(path) and not is_malformed_path(path):
                if any(path.endswith(s) for s in suffixes):
                    count += 1
        return count


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed = [g for g in evaluated if g.passed]
        return len(passed) / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files}, Python Files: {self.python_files}")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append("Gates:")
        for g in self.gates:
            lines.append(f"  [{g.status.upper():7}] {g.name:10} ({g.method}): {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "gate_status": self.gate_status,
            "pass_rate": self.pass_rate
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    # Regex to find fenced code blocks with optional language and optional filename hint
    # Common patterns:
    # ```python
    # ```path/to/file.py
    # ```python path/to/file.py
    # We need to extract content and try to infer path.

    blocks = {}
    # Pattern: ```(lang)?\s*(path)?\n(content)\n```
    # This is tricky because standard markdown doesn't enforce paths.
    # We'll look for ```python ... ``` or ``` ... ```
    # And try to guess path from comments or just use index if no path found.

    # Let's use a more robust regex for fenced blocks
    pattern = r"```(?:\w+)?(?:\s+([^\s`]+))?\n(.*?)\n```"
    matches = re.finditer(pattern, text, re.DOTALL)

    for i, match in enumerate(matches):
        path_hint = match.group(1)
        content = match.group(2)

        if not path_hint:
            # Try to find a filename in the first few lines of content
            lines = content.split('\n')
            for line in lines[:5]:
                # Look for something that looks like a filename
                # e.g. # file: main.py or just main.py
                stripped = line.strip()
                if stripped.startswith('#') and 'file:' in stripped.lower():
                    parts = stripped.split('file:')
                    if len(parts) > 1:
                        path_hint = parts[1].strip()
                        break
                elif stripped.endswith('.py') and ' ' not in stripped:
                    path_hint = stripped
                    break

        if not path_hint:
            path_hint = f"block_{i}.py"

        # Clean up path hint
        path_hint = path_hint.strip()
        if path_hint.startswith('`') and path_hint.endswith('`'):
            path_hint = path_hint[1:-1]

        blocks[path_hint] = content

    return blocks


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        if workspace is not None:
            # Assume workspace has a method to get files or is a dict
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
                source = 'workspace'
            elif isinstance(workspace, dict):
                bundle = workspace
                source = 'workspace'
            else:
                # Try to treat it as a directory path if it's a string
                if isinstance(workspace, str) and os.path.isdir(workspace):
                    return self.verify_directory(workspace, source='directory')

        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        if not bundle:
            # Empty workspace
            return self._create_empty_report(source)

        return self.verify_bundle(bundle, source=source)

    def _create_empty_report(self, source: str) -> VerificationReport:
        gates = [
            GateResult(name='syntax', status=FAILED, method='ast', detail='No Python files found'),
            GateResult(name='build', status=FAILED, method='pip', detail='No packaging metadata found'),
            GateResult(name='smoke', status=FAILED, method='import', detail='No modules to import'),
            GateResult(name='tests', status=FAILED, method='pytest', detail='No tests found'),
            GateResult(name='telemetry', status=FAILED, method='ast', detail='No telemetry found'),
        ]
        return VerificationReport(
            gates=gates,
            score_penalty=len(gates) * self.penalty_per_gate,
            authored_files=0,
            python_files=0,
            source=source
        )

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle using artifacts logic
        authored_bundle = filter_bundle(bundle)

        # Count files
        authored_files = len(authored_bundle)
        python_files = count_source_files(authored_bundle, suffixes=('.py',))

        # Create temp dir
        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files
            for path, content in authored_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=authored_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory
            bundle = {}
            for root, dirs, files in os.walk(workdir):
                # Prune excluded dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]
                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        try:
                            with open(os.path.join(root, file), 'r', encoding='utf-8') as f:
                                bundle[rel_path] = f.read()
                        except Exception:
                            pass
            authored = bundle

        authored_files = len(authored)
        python_files = count_source_files(authored, suffixes=('.py',))

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(workdir, authored))

        # 2. Build Gate
        gates.append(self._gate_build(workdir, authored))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, authored))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, authored))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(workdir, authored))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files,
            python_files=python_files,
            source=source
        )

    def _get_python_files(self, workdir: str, authored: Dict[str, str]) -> List[str]:
        """Returns list of relative paths to .py files in authored bundle."""
        return [p for p in authored.keys() if p.endswith('.py')]

    def _gate_syntax(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        py_files = self._get_python_files(workdir, authored)

        if not py_files:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast',
                detail='No Python files found',
                duration_s=time.time() - start
            )

        errors = []
        for rel_path in py_files:
            full_path = os.path.join(workdir, rel_path)
            try:
                with open(full_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{rel_path}: {e}")
            except Exception as e:
                errors.append(f"{rel_path}: {e}")

        if errors:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast',
                detail='Syntax errors found: ' + '; '.join(errors),
                duration_s=time.time() - start
            )

        return GateResult(
            name='syntax',
            status=PASSED,
            method='ast',
            detail=f"All {len(py_files)} Python files parsed successfully",
            duration_s=time.time() - start
        )

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Check for packaging metadata
        has_pyproject = 'pyproject.toml' in authored
        has_setup_py = 'setup.py' in authored
        has_setup_cfg = 'setup.cfg' in authored

        if not (has_pyproject or has_setup_py or has_setup_cfg):
            return GateResult(
                name='build',
                status=FAILED,
                method='pip',
                detail='No packaging metadata (pyproject.toml, setup.py, setup.cfg) found',
                duration_s=time.time() - start
            )

        # Validate pyproject.toml if present
        if has_pyproject:
            try:
                with open(os.path.join(workdir, 'pyproject.toml'), 'rb') as f:
                    data = tomllib.load(f)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(k in data for k in ['project', 'build-system', 'tool']):
                    return GateResult(
                        name='build',
                        status=FAILED,
                        method='pip',
                        detail='pyproject.toml is valid TOML but missing required tables ([project], [build-system], or [tool])',
                        duration_s=time.time() - start
                    )
            except Exception as e:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='pip',
                    detail=f'pyproject.toml is invalid: {e}',
                    duration_s=time.time() - start
                )

        # Try to install
        # Check if pip is available
        try:
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], 
                           capture_output=True, timeout=10, check=True)
        except Exception:
            return GateResult(
                name='build',
                status=SKIPPED,
                method='pip',
                detail='pip not available',
                duration_s=time.time() - start
            )

        # Run pip install -e . --no-deps --no-build-isolation
        try:
            result = subprocess.run(
                [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation'],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )
            if result.returncode == 0:
                return GateResult(
                    name='build',
                    status=PASSED,
                    method='pip',
                    detail='Package installed successfully',
                    duration_s=time.time() - start
                )
            else:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='pip',
                    detail=f'pip install failed: {result.stderr}',
                    duration_s=time.time() - start
                )
        except subprocess.TimeoutExpired:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip',
                detail='pip install timed out',
                duration_s=time.time() - start
            )
        except Exception as e:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip',
                detail=f'pip install error: {e}',
                duration_s=time.time() - start
            )

    def _gate_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Find non-test authored modules
        # "Non-test authored modules" -> .py files that are not test files
        # Test files are identified by "test" in basename.lower()
        py_files = self._get_python_files(workdir, authored)
        non_test_modules = []

        for rel_path in py_files:
            basename = os.path.basename(rel_path).lower()
            if 'test' not in basename:
                non_test_modules.append(rel_path)

        if not non_test_modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import',
                detail='No non-test modules found',
                duration_s=time.time() - start
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        python_path = f"{workdir}:{src_dir}"

        env = os.environ.copy()
        env['PYTHONPATH'] = python_path

        # Try to import each module in a subprocess
        # We need to convert file paths to module names
        # This is tricky. We'll try to import the file as a module.
        # For simplicity, we'll try to import the top-level package or module.

        # Let's try to import each file directly using importlib in a subprocess
        # Or simpler: run a python script that imports them.

        import_script = []
        for rel_path in non_test_modules:
            # Convert path to module name
            # e.g. src/foo/bar.py -> foo.bar
            # e.g. foo.py -> foo
            path_parts = rel_path.replace('\\', '/').split('/')
            if path_parts[0] == 'src':
                path_parts = path_parts[1:]

            if path_parts[-1] == '__init__.py':
                path_parts = path_parts[:-1]
            elif path_parts[-1].endswith('.py'):
                path_parts[-1] = path_parts[-1][:-3]

            module_name = '.'.join(path_parts)
            if module_name:
                import_script.append(f"import {module_name}")

        if not import_script:
             return GateResult(
                name='smoke',
                status=FAILED,
                method='import',
                detail='No importable modules identified',
                duration_s=time.time() - start
            )

        script_content = "\n".join(import_script)

        try:
            result = subprocess.run(
                [self.python_executable, '-c', script_content],
                cwd=workdir,
                env=env,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            if result.returncode == 0:
                return GateResult(
                    name='smoke',
                    status=PASSED,
                    method='import',
                    detail=f"Successfully imported {len(non_test_modules)} modules",
                    duration_s=time.time() - start
                )
            else:
                stderr = result.stderr
                # Check for ModuleNotFoundError for third-party packages
                if 'ModuleNotFoundError' in stderr:
                    # Check if it's a third-party package (not part of the workspace)
                    # This is heuristic. If the missing module is not in our authored files, it's likely third-party.
                    # We'll assume if it's not a local import, it's third-party.
                    # A simple check: if the error mentions a module that isn't in our bundle.
                    # For now, if we see ModuleNotFoundError, we might skip.
                    # But the spec says: "If module imports fail solely with ModuleNotFoundError for uninstalled third-party packages... return SKIPPED"
                    # If it fails with SyntaxError or other runtime errors, return FAILED.

                    # Let's check if the error is ONLY ModuleNotFoundError
                    # If there are other errors, it's FAILED.
                    if 'SyntaxError' in stderr or 'ImportError' in stderr and 'ModuleNotFoundError' not in stderr:
                         return GateResult(
                            name='smoke',
                            status=FAILED,
                            method='import',
                            detail=f"Import failed: {stderr}",
                            duration_s=time.time() - start
                        )

                    # If it's ModuleNotFoundError, check if it's a local module
                    # This is hard to do perfectly. We'll assume if it's not in our bundle, it's third-party.
                    # If we can't determine, we might default to FAILED to be safe, or SKIPPED.
                    # The spec says "solely with ModuleNotFoundError for uninstalled third-party packages".
                    # If we see ModuleNotFoundError, we'll return SKIPPED.
                    return GateResult(
                        name='smoke',
                        status=SKIPPED,
                        method='import',
                        detail=f"Import failed due to missing third-party package: {stderr}",
                        duration_s=time.time() - start
                    )
                else:
                    return GateResult(
                        name='smoke',
                        status=FAILED,
                        method='import',
                        detail=f"Import failed: {stderr}",
                        duration_s=time.time() - start
                    )

        except subprocess.TimeoutExpired:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import',
                detail='Import timed out',
                duration_s=time.time() - start
            )
        except Exception as e:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import',
                detail=f"Import error: {e}",
                duration_s=time.time() - start
            )

    def _gate_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Discover test files
        py_files = self._get_python_files(workdir, authored)
        test_files = []
        for rel_path in py_files:
            basename = os.path.basename(rel_path).lower()
            if 'test' in basename:
                test_files.append(rel_path)

        if not test_files:
            return GateResult(
                name='tests',
                status=FAILED,
                method='pytest',
                detail='No test files found',
                duration_s=time.time() - start
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        python_path = f"{workdir}:{src_dir}"

        env = os.environ.copy()
        env['PYTHONPATH'] = python_path

        # Check if pytest is installed
        try:
            subprocess.run([self.python_executable, '-m', 'pytest', '--version'], 
                           capture_output=True, timeout=10, check=True)
            has_pytest = True
        except Exception:
            has_pytest = False

        if has_pytest:
            # Run pytest
            try:
                result = subprocess.run(
                    [self.python_executable, '-m', 'pytest', '-v'] + test_files,
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                if result.returncode == 0:
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='pytest',
                        detail='All tests passed',
                        duration_s=time.time() - start
                    )
                else:
                    # Check for ModuleNotFoundError
                    if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                        return GateResult(
                            name='tests',
                            status=SKIPPED,
                            method='pytest',
                            detail=f"Tests skipped due to missing dependencies: {result.stderr}",
                            duration_s=time.time() - start
                        )
                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method='pytest',
                        detail=f"Tests failed: {result.stderr}",
                        duration_s=time.time() - start
                    )
            except subprocess.TimeoutExpired:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest',
                    detail='Tests timed out',
                    duration_s=time.time() - start
                )
            except Exception as e:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest',
                    detail=f"Pytest error: {e}",
                    duration_s=time.time() - start
                )
        else:
            # Stdlib fallback
            # Run a subprocess that imports each test file and collects/executes 
            # bare def test_*() functions AND unittest.TestCase subclasses

            # We'll write a small runner script
            runner_script = """
import sys
import os
import unittest
import importlib.util

def run_tests(test_files):
    collected = 0
    failed = 0

    for test_file in test_files:
        try:
            # Add to path
            sys.path.insert(0, os.path.dirname(test_file))
            spec = importlib.util.spec_from_file_location("test_module", test_file)
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)

            # Collect bare test functions
            for name in dir(module):
                if name.startswith('test_'):
                    func = getattr(module, name)
                    if callable(func) and func.__code__.co_argcount == 0:
                        collected += 1
                        try:
                            func()
                        except Exception as e:
                            failed += 1
                            print(f"FAIL: {name}: {e}")

            # Collect unittest.TestCase subclasses
            for name in dir(module):
                cls = getattr(module, name)
                if isinstance(cls, type) and issubclass(cls, unittest.TestCase) and cls is not unittest.TestCase:
                    suite = unittest.TestLoader().loadTestsFromTestCase(cls)
                    collected += suite.countTestCases()
                    result = unittest.TextTestRunner(verbosity=0).run(suite)
                    if not result.wasSuccessful():
                        failed += len(result.failures) + len(result.errors)

        except ModuleNotFoundError as e:
            print(f"SKIP: {test_file}: {e}")
            return 'SKIPPED'
        except Exception as e:
            print(f"ERROR: {test_file}: {e}")
            return 'FAILED'

    if collected == 0:
        return 'FAILED'
    if failed > 0:
        return 'FAILED'
    return 'PASSED'

if __name__ == '__main__':
    test_files = sys.argv[1:]
    status = run_tests(test_files)
    print(status)
    sys.exit(0 if status == 'PASSED' else 1)
"""

            try:
                result = subprocess.run(
                    [self.python_executable, '-c', runner_script] + test_files,
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                output = result.stdout.strip()
                if output.endswith('PASSED'):
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='stdlib',
                        detail='All tests passed (stdlib runner)',
                        duration_s=time.time() - start
                    )
                elif output.endswith('SKIPPED'):
                    return GateResult(
                        name='tests',
                        status=SKIPPED,
                        method='stdlib',
                        detail=f"Tests skipped due to missing dependencies: {result.stderr}",
                        duration_s=time.time() - start
                    )
                else:
                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method='stdlib',
                        detail=f"Tests failed: {result.stderr}",
                        duration_s=time.time() - start
                    )
            except subprocess.TimeoutExpired:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='stdlib',
                    detail='Tests timed out',
                    duration_s=time.time() - start
                )
            except Exception as e:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='stdlib',
                    detail=f"Test runner error: {e}",
                    duration_s=time.time() - start
                )

    def _gate_telemetry(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        py_files = self._get_python_files(workdir, authored)

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span', 'start_span', 'get_tracer', 
            'get_tracer_provider', 'set_tracer_provider', 'get_meter'
        }

        for rel_path in py_files:
            full_path = os.path.join(workdir, rel_path)
            try:
                with open(full_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                tree = ast.parse(content)

                for node in ast.walk(tree):
                    # Check for import opentelemetry or from opentelemetry ... import ...
                    if isinstance(node, ast.Import):
                        for alias in node.names:
                            if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                                has_import = True
                    elif isinstance(node, ast.ImportFrom):
                        if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                            has_import = True

                    # Check for calls to tracer/span methods
                    if isinstance(node, ast.Call):
                        func = node.func
                        # Handle attribute access like tracer.start_span()
                        if isinstance(func, ast.Attribute):
                            if func.attr in tracer_methods:
                                has_call = True
                        # Handle direct function calls like get_tracer()
                        elif isinstance(func, ast.Name):
                            if func.id in tracer_methods:
                                has_call = True

            except Exception:
                continue

        if has_import and has_call:
            return GateResult(
                name='telemetry',
                status=PASSED,
                method='ast',
                detail='OpenTelemetry import and tracer/span calls found',
                duration_s=time.time() - start
            )
        elif has_import:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast',
                detail='OpenTelemetry import found but no tracer/span calls',
                duration_s=time.time() - start
            )
        else:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast',
                detail='No OpenTelemetry usage found',
                duration_s=time.time() - start
            )

